using System;
using System.Threading;
using System.Timers;
// Note: System.Windows.Forms is NOT available outside of net10.0-windows TFM.
// The snippets below cover both the Forms.Timer and the Thread.Sleep polling pattern.

// Pattern 1 — System.Windows.Forms.Timer (UI thread affinity).
// CANNOT be used in an ASP.NET Core or Worker Service project at all.
// Forms.Timer fires on the UI SynchronizationContext. If there is no
// UI thread, it never fires.
public class FormsTimerExample
{
    private System.Windows.Forms.Timer _timer;

    public void Start()
    {
        _timer = new System.Windows.Forms.Timer();
        _timer.Interval = 5000;           // 5 seconds
        _timer.Tick += OnTick;
        _timer.Start();
    }

    private void OnTick(object sender, EventArgs e)
    {
        // Run background work on the UI thread — this blocks the GUI.
        DoWork();
    }

    private void DoWork() { /* ... */ }
}

// Pattern 2 — Thread.Sleep polling loop inside a ThreadPool thread.
// Works in Framework; in .NET 10 BackgroundService should be used instead.
public class SleepPollingService
{
    private bool _running;

    public void Start()
    {
        _running = true;
        ThreadPool.QueueUserWorkItem(_ =>
        {
            while (_running)
            {
                ProcessBatch();
                Thread.Sleep(10000); // sleep 10 seconds between batches
            }
        });
    }

    public void Stop() => _running = false;

    private void ProcessBatch() { /* ... */ }
}
